async () => {
const get = async u => (await (await fetch(u)).text());
const rows = t => [...new DOMParser().parseFromString(t,'text/html').querySelectorAll('#the-list tr')].map(r=>r.id+': '+r.querySelector('.row-title')?.textContent);
const notice = (await get('/wp-admin/edit.php?post_type=post')).match(/moved to the Trash/);
return {trash: rows(await get('/wp-admin/edit.php?post_status=trash&post_type=post')),
 published: rows(await get('/wp-admin/edit.php?post_status=publish&post_type=post')),
 front4: (await fetch('/?p=7')).status, front5: (await fetch('/?p=8')).status, front6:(await fetch('/?p=9')).status};
}

